CREATE TABLE IF NOT EXISTS projects (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, "key" VARCHAR(10) NOT NULL, description VARCHAR(2000), lead_id VARCHAR(36), visibility VARCHAR(20) DEFAULT 'private', status VARCHAR(20) DEFAULT 'active', settings VARCHAR(2000) DEFAULT '{}', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_pages (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, project_id VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, content VARCHAR(10000), category VARCHAR(50) DEFAULT 'general', status VARCHAR(20) DEFAULT 'draft', created_by VARCHAR(36), updated_by VARCHAR(36), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS issues (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, project_id VARCHAR(36) NOT NULL, issue_number INT DEFAULT 0, title VARCHAR(500) NOT NULL, description TEXT, type VARCHAR(20) DEFAULT 'task', status VARCHAR(50) DEFAULT 'open', priority VARCHAR(20) DEFAULT 'medium', assignee_id VARCHAR(36), reporter_id VARCHAR(36), sprint_id VARCHAR(36), parent_id VARCHAR(36), story_points DOUBLE, labels VARCHAR(1000), security_level VARCHAR(20) DEFAULT 'none', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments (id VARCHAR(36) PRIMARY KEY, issue_id VARCHAR(36) NOT NULL, author_id VARCHAR(36), author_name VARCHAR(100), body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_keys (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, key_prefix VARCHAR(8), key_hash VARCHAR(255) NOT NULL UNIQUE, scopes VARCHAR(500) DEFAULT 'read,write', last_used_at TIMESTAMP, expires_at TIMESTAMP, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id, user_id, name));
CREATE TABLE IF NOT EXISTS hitl_configs (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, agent_name VARCHAR(100), mode VARCHAR(20) DEFAULT 'manual', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
